package com.bank.maturity.score;

// SENIOR axis: is the architecture technically correct?
public class TechnicalScore {
    private final boolean cleanBoundaries;
    private final boolean dataOwnership;     // no shared DB
    private final boolean resiliencePatterns;// timeouts, breakers, bulkheads
    private final boolean observability;     // tracing, metrics, logs
    private final boolean failureReasoning;  // handles duplicates, crashes, slowness

    public TechnicalScore(boolean b, boolean d, boolean r, boolean o, boolean f) {
        this.cleanBoundaries=b; this.dataOwnership=d; this.resiliencePatterns=r;
        this.observability=o; this.failureReasoning=f;
    }
    public double score() {
        int yes = (cleanBoundaries?1:0)+(dataOwnership?1:0)+(resiliencePatterns?1:0)
                + (observability?1:0)+(failureReasoning?1:0);
        return yes / 5.0;
    }
}
