package com.bank.maturity.score;

// STAFF axis: SHOULD the organization pay the permanent cost?
public class OrganizationalScore {
    private final boolean boundariesMatchTeams; // ownership + on-call sustainable
    private final boolean taxJustified;         // platform cost worth the value
    private final boolean debuggableByNewHire;  // can someone recover it at 3 AM
    private final boolean contractsEvolvable;   // versioned, backward-compatible
    private final boolean reversible;           // services can be merged back

    public OrganizationalScore(boolean t, boolean x, boolean d, boolean c, boolean r) {
        this.boundariesMatchTeams=t; this.taxJustified=x; this.debuggableByNewHire=d;
        this.contractsEvolvable=c; this.reversible=r;
    }
    public double score() {
        int yes = (boundariesMatchTeams?1:0)+(taxJustified?1:0)+(debuggableByNewHire?1:0)
                + (contractsEvolvable?1:0)+(reversible?1:0);
        return yes / 5.0;
    }
}
