package com.bank.maturity.decision;

import com.bank.maturity.score.OrganizationalScore;
import com.bank.maturity.score.TechnicalScore;
import java.util.logging.Logger;

// A technically perfect design can still be the WRONG organizational choice.
public class MaturityAdvisor {
    private static final Logger log = Logger.getLogger(MaturityAdvisor.class.getName());
    private final double minTech, minOrg;
    public MaturityAdvisor(double minTech, double minOrg) { this.minTech=minTech; this.minOrg=minOrg; }

    public String advise(TechnicalScore tech, OrganizationalScore org) {
        double t = tech.score(), o = org.score();
        log.info(() -> String.format("technical=%.2f (senior)  organizational=%.2f (staff)", t, o));
        if (t >= minTech && o < minOrg) {
            log.warning("Technically sound but org cost NOT justified → the staff-level NO");
            return "REJECT_ORG_COST_TOO_HIGH";
        }
        if (t < minTech) {
            log.warning("Not even technically sound yet");
            return "REJECT_FIX_DESIGN";
        }
        log.info("Technically sound AND organizationally sustainable");
        return "APPROVE";
    }
}
