package com.bank.maturity;

import com.bank.maturity.decision.MaturityAdvisor;
import com.bank.maturity.score.OrganizationalScore;
import com.bank.maturity.score.TechnicalScore;
import java.util.logging.*;

public class MaturityDemo {
    private static final Logger log = Logger.getLogger(MaturityDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }
    public static void main(String[] args) {
        MaturityAdvisor advisor = new MaturityAdvisor(0.7, 0.7);

        // Proposal: split payments into 8 microservices.
        // SENIOR view: technically excellent — everything right.
        TechnicalScore tech = new TechnicalScore(true, true, true, true, true); // 1.0

        // STAFF view: boundaries don't match teams, tax not justified,
        // a new hire can't debug 8 services at 3 AM, not reversible.
        OrganizationalScore org = new OrganizationalScore(false, false, false, true, false); // 0.2

        log.info("=== Senior (technical) vs Staff/Principal (organizational) ===");
        String verdict = advisor.advise(tech, org);
        log.info(() -> "VERDICT: " + verdict);
        log.info("Staff reframing: not 'can microservices solve this' but 'should we pay the permanent cost'");
    }
}

